import pennylane as qml
from pennylane import numpy as np
import numpy as onp

np.random.seed(42)

dev = qml.device("default.qubit", wires=1)

def square_loss(targets, predictions):
    loss = 0
    for t, p in zip(targets, predictions):
        loss = loss + (t - p) ** 2
    return loss / len(targets)

def data_reuploading(weights, x):
    for l in range(4):
        qml.RZ(x, wires=0)
        qml.RY(weights[l], wires=0)

@qml.qnode(dev)
def circuit(weights, x):
    data_reuploading(weights, x)
    return qml.expval(qml.PauliZ(0))

def cost(weights, X, Y):
    predictions = [circuit(weights, x) for x in X]
    return square_loss(Y, predictions)

X = np.linspace(0, 2 * np.pi, 30, requires_grad=False)
Y = np.cos(2 * X)

weights = np.random.randn(4, requires_grad=True)

opt = qml.AdamOptimizer(stepsize=0.05)
batch_size = 10
epochs = 200

for epoch in range(epochs):
    batch_index = onp.random.randint(0, len(X), size=batch_size)
    X_batch = X[batch_index]
    Y_batch = Y[batch_index]
    weights = opt.step(lambda w: cost(w, X_batch, Y_batch), weights)
    if (epoch + 1) % 50 == 0:
        current_loss = cost(weights, X, Y)
        print(f"Epoch {epoch + 1}: Loss = {current_loss:.6f}")

final_loss = cost(weights, X, Y)
print(f"Final loss: {final_loss:.6f}")

import pennylane as qml
from pennylane import numpy as np
import itertools

edges = [(0, 1), (0, 3), (1, 2), (2, 3)]
n_qubits = 4
p = 3

dev = qml.device("default.qubit", wires=n_qubits, shots=None)

def cost_layer(gamma):
    for (i, j) in edges:
        qml.CNOT(wires=[i, j])
        qml.RZ(2 * gamma, wires=j)
        qml.CNOT(wires=[i, j])

def mixer_layer(alpha):
    for i in range(n_qubits):
        qml.RX(2 * alpha, wires=i)

@qml.qnode(dev)
def circuit(params):
    gammas, alphas = params[:p], params[p:]
    for i in range(n_qubits):
        qml.Hadamard(wires=i)
    for layer in range(p):
        cost_layer(gammas[layer])
        mixer_layer(alphas[layer])
    return qml.probs(wires=range(n_qubits))

def objective(params):
    probs = circuit(params)
    cost = 0.0
    for state in range(2 ** n_qubits):
        bitstring = format(state, f"0{n_qubits}b")
        cut = 0
        for (i, j) in edges:
            if bitstring[i] != bitstring[j]:
                cut += 1
        cost -= cut * probs[state]
    return cost

np.random.seed(42)
init_params = np.random.uniform(0, np.pi, 2 * p, requires_grad=True)
params = init_params
opt = qml.AdamOptimizer(stepsize=0.05)

for step in range(300):
    params = opt.step(objective, params)

probs = circuit(params)
best_state = int(np.argmax(probs))
best_bitstring = format(best_state, f"0{n_qubits}b")
best_cut = 0
for (i, j) in edges:
    if best_bitstring[i] != best_bitstring[j]:
        best_cut += 1

print(f"Parameters: {params}")
print(f"Most probable bitstring: {best_bitstring}")
print(f"Cut value: {best_cut}")

import pennylane as qml
from pennylane import numpy as np


def build_circuit_and_optimize():
    dev = qml.device("default.qubit", wires=4)

    coeffs = [1.0, 1.0, 1.0]
    obs = [qml.Z(0) @ qml.Z(1), qml.X(0) @ qml.X(2), qml.Y(1) @ qml.Y(3)]
    H = qml.Hamiltonian(coeffs, obs)

    @qml.qnode(dev)
    def circuit(params):
        for i in range(4):
            qml.RX(params[i], wires=i)
        qml.CNOT(wires=[0, 1])
        qml.CNOT(wires=[2, 3])
        qml.CNOT(wires=[1, 2])
        qml.CNOT(wires=[0, 3])
        return qml.expval(H)

    def cost(params):
        return circuit(params)

    np.random.seed(42)
    params = np.random.uniform(-np.pi, np.pi, 6, requires_grad=True)

    optimizer = qml.GradientDescentOptimizer(stepsize=0.1)
    max_iterations = 500
    conv_tol = 1e-06

    for n in range(max_iterations):
        params, prev_cost = optimizer.step_and_cost(cost, params)
        cost_val = cost(params)
        if n % 50 == 0 or n == max_iterations - 1:
            print(f"Step = {n:4d}, Cost = {cost_val:.8f}")
        if abs(prev_cost - cost_val) < conv_tol:
            print(f"Converged at step {n}, Cost = {cost_val:.8f}")
            break

    return params, cost_val


def main():
    params, final_cost = build_circuit_and_optimize()
    print("Final parameters:", params)
    print("Final cost:", final_cost)


if __name__ == "__main__":
    main()

