from math import gcd
from fractions import Fraction
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator

def qft_dagger(qc, n):
    for q in range(n // 2):
        qc.swap(q, n - q - 1)
    for j in range(n):
        for k in range(j):
            qc.cp(-np.pi / float(2 ** (j - k)), k, j)
        qc.h(j)

def cmodmul_15_13(qc, ctl, q):
    qc.cswap(ctl, q[0], q[1])
    qc.cswap(ctl, q[1], q[2])
    qc.cswap(ctl, q[2], q[3])

def order_finding_circuit(n_count, a, N):
    qc = QuantumCircuit(n_count + 4, n_count)
    for q in range(n_count):
        qc.h(q)
    qc.x(n_count + 3)
    for i in range(n_count):
        cmodmul_15_13(qc, i, [n_count, n_count + 1, n_count + 2, n_count + 3])
    qft_dagger(qc, n_count)
    qc.measure(range(n_count), range(n_count))
    return qc

def get_factors_from_phase(phase, n_count, a, N):
    if phase == 0:
        return None
    frac = Fraction(phase).limit_denominator(N - 1)
    s, r = frac.numerator, frac.denominator
    if r % 2 != 0:
        return None
    if pow(a, r, N) == N - 1:
        return None
    apow = pow(a, r // 2, N)
    f1 = gcd(apow - 1, N)
    f2 = gcd(apow + 1, N)
    if 1 < f1 < N and 1 < f2 < N:
        return sorted([f1, f2])
    return None

def main():
    N = 15
    a = 13
    n_count = 4
    qc = order_finding_circuit(n_count, a, N)
    backend = AerSimulator()
    tqc = transpile(qc, backend)
    job = backend.run(tqc, shots=4096)
    result = job.result()
    counts = result.get_counts()
    print("Measurement counts:", counts)
    found = None
    for measured in sorted(counts, key=lambda x: counts[x], reverse=True):
        phase = int(measured, 2) / (2 ** n_count)
        factors = get_factors_from_phase(phase, n_count, a, N)
        if factors:
            found = factors
            break
    if found:
        print(f"Factors of {N}: {found[0]} and {found[1]}")
    else:
        print("Failed to find factors in this run.")

if __name__ == "__main__":
    main()

