QSHARP_CODE = r'''
namespace Bell {
    open Microsoft.Quantum.Measurement;

    operation PrepareBellState() : (Result, Result) {
        use (q1, q2) = (Qubit(), Qubit());
        H(q1);
        CNOT(q1, q2);
        return (MResetZ(q1), MResetZ(q2));
    }
