import math
import numpy as np
from fractions import Fraction
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator

def c_amod15(a, power):
    if a not in [2, 4, 7, 8, 11, 13, 14]:
        raise ValueError("'a' must be in [2,4,7,8,11,13,14]")
    U = QuantumCircuit(4)
    for _ in range(power):
        if a in [2, 13]:
            U.swap(2, 3); U.swap(1, 2); U.swap(0, 1)
        if a in [7, 8]:
            U.swap(0, 1); U.swap(1, 2); U.swap(2, 3)
        if a in [4, 11]:
            U.swap(1, 3); U.swap(0, 2)
        if a in [7, 11, 13, 14]:
            for q in range(4):
                U.x(q)
    U = U.to_gate()
    U.name = f"{a}^{power} mod 15"
    cU = U.control()
    return cU

def qpe_amod15(a, n_count=8):
    qc = QuantumCircuit(n_count + 4, n_count)
    for q in range(n_count):
        qc.h(q)
    qc.x(n_count)
    for q in range(n_count):
        qc.append(c_amod15(a, 2**q), [q] + [n_count + i for i in range(4)])
    for q in range(n_count // 2):
        qc.swap(q, n_count - 1 - q)
    for j in range(n_count):
        for k in range(j):
            qc.cp(-np.pi / float(2**(j - k)), k, j)
        qc.h(j)
    qc.measure(range(n_count), range(n_count))
    return qc

def get_factors(N, a, measurement):
    n_count = len(measurement)
    phase = int(measurement, 2) / (2 ** n_count)
    if phase == 0:
        return None
    frac = Fraction(phase).limit_denominator(N)
    r = frac.denominator
    if r % 2 == 1:
        return None
    a_pow_r_half = pow(a, r // 2, N)
    if a_pow_r_half == N - 1:
        return None
    p = math.gcd(a_pow_r_half - 1, N)
    q = math.gcd(a_pow_r_half + 1, N)
    if 1 < p < N and 1 < q < N and p * q == N:
        return (p, q)
    return None

def main():
    N = 15
    a = 2
    n_count = 8
    backend = AerSimulator()
    qc = qpe_amod15(a, n_count)
    transpiled = transpile(qc, backend, optimization_level=0)
    factors = None
    for _ in range(50):
        result = backend.run(transpiled, shots=1, memory=True).result()
        measurement = result.get_memory()[0]
        factors = get_factors(N, a, measurement)
        if factors is not None:
            print(f"Measurement: {measurement}")
            print(f"Factors of {N}: {factors[0]} and {factors[1]}")
            return
    print("Failed to find factors.")

if __name__ == "__main__":
    main()

import numpy as np
import warnings
from collections import Counter
with warnings.catch_warnings():
    warnings.simplefilter("ignore", DeprecationWarning)
    import qsharp

QSHARP_CODE = r'''
namespace QuantumTeleport {
    open Microsoft.Quantum.Diagnostics;
    open Microsoft.Quantum.Measurement;

    operation PrepareRyState(q : Qubit) : Unit {
        Ry(2.399, q);
    }

    operation TeleportRyState() : Result {
        // msg: qubit holding the state to teleport
        // here: Alice's half of the Bell pair
        // there: Bob's half of the Bell pair (receives the teleported state)
        use (msg, here, there) = (Qubit(), Qubit(), Qubit());
        // Prepare the state to teleport on msg
        PrepareRyState(msg);
        // Create Bell pair |Phi+> = (|00>+|11>)/sqrt(2) on (here, there)
        H(here);
        CNOT(here, there);
        // Bell measurement: CNOT(msg, here) then H(msg), then measure msg and here
        CNOT(msg, here);
        H(msg);
        let m1 = MResetZ(msg);
        let m2 = MResetZ(here);
        // Conditional corrections on Bob's qubit (there)
        if m2 == One {
            X(there);
        }
        if m1 == One {
            Z(there);
        }
        return MResetZ(there);
    }
}
'''

def main():
