qsharp_code = r"""
// Oracle for marked state |0111> (q[0]=1, q[1]=1, q[2]=1, q[3]=0)
// Flip q[3] with X to turn |0111> into |1111>, apply CCZ, undo X.
operation Oracle0111(qs : Qubit[]) : Unit {
    X(qs[3]);
    Controlled Z([qs[1], qs[2], qs[3]], qs[0]);
    X(qs[3]);
}

operation Diffusion(qs : Qubit[]) : Unit {
    ApplyToEach(H, qs);
    ApplyToEach(X, qs);
    Controlled Z([qs[1], qs[2], qs[3]], qs[0]);
    ApplyToEach(X, qs);
    ApplyToEach(H, qs);
}

operation GroverSearch() : Result[] {
    use qs = Qubit[4];
    ApplyToEach(H, qs);
    for _ in 1..2 {
        Oracle0111(qs);
        Diffusion(qs);
    }
    mutable res = [One, One, One, One];
    for i in 0..3 {
        set res w/= i <- M(qs[i]);
    }
    ResetAll(qs);
    return res;
}
"""

