        for m in range(j):
            qc.cp(-np.pi / float(2 ** (j - m)), m, j)
        qc.h(j)


def qpe_order_finding(a, N, n_count=8):
    """Run QPE and return a list of candidate periods from the top measurements."""
    n_work = max(1, int(ceil(log2(N))))
    qc = QuantumCircuit(n_count + n_work, n_count)
    counting = list(range(n_count))
    work = list(range(n_count, n_count + n_work))

    for q in counting:
        qc.h(q)
    qc.x(work[0])

    for k in range(n_count):
        a_pow = pow(a, 2 ** k, N)
        if a_pow == 1:
            continue
        if N == 15 and a in [2, 4, 7, 8, 11, 13, 14]:
            U = c_amod15(a, 2 ** k, N)
            qc.append(U, [counting[k]] + work)
        else:
            size = 2 ** n_work
            mat = np.zeros((size, size), dtype=complex)
            for x in range(size):
                if gcd(x, N) == 1:
                    mat[(a_pow * x) % N, x] = 1
                else:
                    mat[x, x] = 1
            Ugate = UnitaryGate(mat, label=f"U{a_pow}").control(1)
            qc.append(Ugate, [counting[k]] + work)

    qft_dagger(qc, n_count)
    qc.measure(counting, list(range(n_count)))

    sim = AerSimulator()
    tqc = transpile(qc, sim)
    counts = sim.run(tqc, shots=4096).result().get_counts()
    print(f"Measurement counts: {counts}")

    # Collect candidate periods from all measured outcomes
    candidates = []
    for measured, c in sorted(counts.items(), key=lambda kv: -kv[1]):
        phase = int(measured, 2) / 2 ** n_count
        if phase == 0:
            continue
        frac = Fraction(phase).limit_denominator(N)
        if frac.denominator > 1:
            candidates.append(frac.denominator)
    return candidates


def shors_algorithm(N, a):
    if gcd(a, N) != 1:
        return gcd(a, N), N // gcd(a, N)

    n_count = 8
    candidates = qpe_order_finding(a, N, n_count)

    # Try each candidate period; the true period r must be even and satisfy
    # a^r = 1 (mod N). Multiples of the true period also appear, so we also
    # try dividing by small factors.
    seen = set()
    for r in candidates:
        for cand_r in [r, r // 2, r // 3, r // 4, 2 * r, 3 * r, 4 * r]:
            if cand_r < 2 or cand_r in seen:
                continue
            seen.add(cand_r)
            if pow(a, cand_r, N) != 1:
                continue
            if cand_r % 2 != 0:
                continue
            if pow(a, cand_r // 2, N) == N - 1:
                continue
            p = gcd(a ** (cand_r // 2) - 1, N)
            q = gcd(a ** (cand_r // 2) + 1, N)
            if p not in [1, N] and q not in [1, N] and p * q == N:
                return p, q
    return None, None


if __name__ == "__main__":
    N = 15
    a = 11

    print(f"Factoring N = {N} with base a = {a}")
    p, q = shors_algorithm(N, a)

    if p is not None and q is not None:
        print(f"Recovered factors: {p} and {q}")
        print(f"Verification: {p} * {q} = {p * q}")
    else:
        print("Failed to find non-trivial factors.")

import numpy as np
from scipy.stats import chisquare
import qsharp

# Modern Q# (qdk) API: init with a target profile, then use qsharp.eval / qsharp.run.
# The new QDK capabilities checker rejects `if <Result> == One` (dynamic classical
# feedback) for QIR targets, so the feed-forward corrections are applied *coherently*
# using the unmeasured msg/here qubits as controls before the final measurement.
# This is the standard unitary-teleportation circuit and reproduces the corrected
# receiver statistics exactly.
qsharp.init(target_profile=qsharp.TargetProfile.Unrestricted)

QSHARP_CODE = r"""
open Microsoft.Quantum.Measurement;

operation PrepareRyState(q : Qubit) : Unit {
    Ry(2.538, q);
}

operation TeleportRyState() : Result {
    use (msg, here, there) = (Qubit(), Qubit(), Qubit());
    // Prepare Ry(2.538)|0> on msg
    PrepareRyState(msg);
    // Create Bell pair (here, there)
    H(here);
    CNOT(here, there);
    // Bell measurement (coherent): CNOT msg->here, H msg
    CNOT(msg, here);
    H(msg);
    // Coherent X/Z corrections on the receiver using msg and here as controls.
    // After H(msg), msg is in the measurement basis; a Z correction on `there`
    // controlled on msg == |1> implements the phase flip, and an X correction
    // controlled on here == |1> implements the bit flip.
    Controlled Z([msg], there);
    Controlled X([here], there);
    // Measure the receiver
    let result = MResetZ(there);
    Reset(msg);
    Reset(here);
    return result;
}
"""
qsharp.eval(QSHARP_CODE)

shots = 1000
results = qsharp.run("TeleportRyState()", shots)

ones = sum(1 for r in results if str(r) == "One")
zeros = shots - ones

theta = 2.538
p0_theory = np.cos(theta / 2) ** 2
p1_theory = np.sin(theta / 2) ** 2

exp0 = shots * p0_theory
exp1 = shots * p1_theory
chi2_stat, p_value = chisquare([zeros, ones], [exp0, exp1])

print("=" * 60)
print("Quantum teleportation (Ry(2.538)|0>) — modern Q# / qdk")
print("Coherent (unitary) feed-forward corrections")
print("=" * 60)
print(f"Shots: {shots}")
print(f"Receiver |0> count: {zeros}")
print(f"Receiver |1> count: {ones}")
print(f"Observed P(|0>): {zeros/shots:.4f}")
print(f"Observed P(|1>): {ones/shots:.4f}")
print()
print(f"Theoretical P(|0>): {p0_theory:.4f}")
print(f"Theoretical P(|1>): {p1_theory:.4f}")
print()
print(f"Expected |0> count: {exp0:.2f}")
print(f"Expected |1> count: {exp1:.2f}")
print()
print(f"Chi-square statistic: {chi2_stat:.4f}")
print(f"P-value: {p_value:.4f}")
if p_value > 0.01:
    print("Result: PASS - Observed distribution matches theory (p > 0.01)")
else:
    print("Result: FAIL - Observed distribution deviates from theory (p <= 0.01)")

import pennylane as qml
from pennylane import numpy as np

np.random.seed(42)

dev = qml.device("default.qubit", wires=1)

def square_loss(labels, predictions):
    loss = 0
    for l, p in zip(labels, predictions):
        loss = loss + (l - p) ** 2
    return loss / len(labels)

def accuracy(labels, predictions):
    acc = 0
    for l, p in zip(labels, predictions):
        if np.abs(l - p) < 1e-5:
            acc = acc + 1
    return acc / len(labels)

def layer(W):
    qml.Rot(W[0, 0], W[0, 1], W[0, 2], wires=0)

@qml.qnode(dev)
def circuit(weights, x):
    qml.RX(x, wires=0)
    for W in weights:
        layer(W)
    return qml.expval(qml.PauliZ(0))

def variational_classifier(weights, x):
    return circuit(weights, x)

def cost(weights, X, Y):
    predictions = [variational_classifier(weights, x) for x in X]
    return square_loss(Y, predictions)

X = np.linspace(-np.pi, np.pi, 30, requires_grad=False)
Y = np.array([1.0 if np.sin(1 * x) >= 0 else -1.0 for x in X], requires_grad=False)

num_layers = 3
weights_init = 0.01 * np.random.randn(num_layers, 1, 3, requires_grad=True)

opt = qml.GradientDescentOptimizer(stepsize=0.1)
batch_size = 10
weights = weights_init

for it in range(100):
    batch_index = np.random.randint(0, len(X), (batch_size,))
    X_batch = X[batch_index]
    Y_batch = Y[batch_index]
    weights, _, _ = opt.step(cost, weights, X_batch, Y_batch)

    if it % 10 == 0 or it == 99:
        predictions = [np.sign(variational_classifier(weights, x)) for x in X]
        acc = accuracy(Y, predictions)
        current_cost = cost(weights, X, Y)
        print(f"Iter: {it+1:4d} | Cost: {current_cost:0.7f} | Accuracy: {acc:0.7f}")

final_predictions = [np.sign(variational_classifier(weights, x)) for x in X]
final_acc = accuracy(Y, final_predictions)
print(f"Final training accuracy: {final_acc:0.7f}")

