from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
import numpy as np

def simon_oracle(qc, s):
    n = len(s)
    for i in range(n):
        qc.cx(i, n + i)
    for i, bit in enumerate(reversed(s)):
        if bit == '1':
            qc.cx(i, n + i)

def solve_linear_system(equations, n):
    rows = []
    for eq in equations:
        rows.append([int(x) for x in eq])
    A = np.array(rows, dtype=int)
    m = A.shape[0]
    rank = 0
    pivot_cols = []
    for col in range(n):
        pivot = None
        for r in range(rank, m):
            if A[r, col] == 1:
                pivot = r
                break
        if pivot is None:
            continue
        A[[rank, pivot]] = A[[pivot, rank]]
        for r in range(m):
            if r != rank and A[r, col] == 1:
                A[r] = (A[r] + A[rank]) % 2
        pivot_cols.append(col)
        rank += 1
        if rank == m:
            break
    free_vars = [c for c in range(n) if c not in pivot_cols]
    solutions = []
    for mask in range(1 << len(free_vars)):
        x = np.zeros(n, dtype=int)
        for i, fv in enumerate(free_vars):
            x[fv] = (mask >> i) & 1
        for r in range(rank):
            pc = pivot_cols[r]
            x[pc] = A[r, n - 1] if n - 1 in pivot_cols else 0
            val = 0
            for c in range(n):
                if c != pc and A[r, c] == 1:
                    val ^= x[c]
            x[pc] = val
        if np.all((A[:, :n] @ x) % 2 == 0):
            s_str = ''.join(str(int(b)) for b in reversed(x))
            if s_str != '0' * n:
                solutions.append(s_str)
    return solutions

s = '01001'
n = len(s)
qc = QuantumCircuit(2 * n, n)
for i in range(n):
    qc.h(i)
simon_oracle(qc, s)
for i in range(n):
    qc.h(i)
qc.measure(range(n), range(n))

simulator = AerSimulator()
t_qc = transpile(qc, simulator)
result = simulator.run(t_qc, shots=1024).result()
counts = result.get_counts()

equations = [k.replace(' ', '') for k in counts.keys()]
solutions = solve_linear_system(equations, n)

print("Measurement counts:", counts)
print("Recovered period s:", solutions[0] if solutions else "Not found")

import pennylane as qml
from pennylane import numpy as np
import networkx as nx

edges = [(0, 1), (0, 3), (0, 4), (1, 3), (2, 3)]
G = nx.Graph()
G.add_edges_from(edges)
n_qubits = G.number_of_nodes()

dev = qml.device("default.qubit", wires=n_qubits, shots=None)

def cost_layer(gamma):
    for i, j in G.edges():
        qml.CNOT(wires=[i, j])
        qml.RZ(2 * gamma, wires=j)
        qml.CNOT(wires=[i, j])

def mixer_layer(alpha):
    for i in range(n_qubits):
        qml.RX(2 * alpha, wires=i)

@qml.qnode(dev)
def circuit(params):
    gamma, alpha = params
    for i in range(n_qubits):
        qml.Hadamard(wires=i)
    cost_layer(gamma)
    mixer_layer(alpha)
    return qml.probs(wires=range(n_qubits))

def cost(params):
    probs = circuit(params)
    exp = 0.0
    for state, prob in enumerate(probs):
        if prob == 0:
            continue
        cut = 0
        for i, j in G.edges():
            if ((state >> i) & 1) != ((state >> j) & 1):
                cut += 1
        exp += prob * cut
    return -exp

np.random.seed(42)
params = np.random.uniform(0, np.pi, 2, requires_grad=True)
opt = qml.AdamOptimizer(stepsize=0.05)

for it in range(300):
    params = opt.step(cost, params)

probs = circuit(params)
best_state = int(np.argmax(probs))
best_bs = format(best_state, f"0{n_qubits}b")

cut_val = 0
for i, j in G.edges():
    if ((best_state >> i) & 1) != ((best_state >> j) & 1):
        cut_val += 1

print(f"Optimized parameters: gamma={float(params[0]):.6f}, alpha={float(params[1]):.6f}")
print(f"Most probable bitstring: {best_bs}")
print(f"Cut value: {cut_val}")

