from pytket.circuit import Circuit
from pytket.passes import FullPeepholeOptimise
from pytket.transform import CXConfigType
from pytket.architecture import Architecture
from pytket.predicates import CompilationUnit

def count_gates(circ):
    counts = {}
    for cmd in circ.get_commands():
        g = cmd.op.get_type()
        counts[g] = counts.get(g, 0) + 1
    return counts

def main():
    n = 5
    circ = Circuit(n)

    # Layer 1
    for q in range(n):
        circ.H(q)
    for q in range(n - 1):
        circ.CX(q, q + 1)
    for q in range(n):
        circ.Rz(0.3, q)

    # Layer 2
    for q in range(n):
        circ.H(q)
    for q in range(n - 1):
        circ.CX(q, q + 1)
    for q in range(n):
        circ.Rz(0.5, q)

    # Layer 3
    for q in range(n):
        circ.H(q)
    for q in range(n - 1):
        circ.CX(q, q + 1)
    for q in range(n):
        circ.Rz(0.7, q)

    before = count_gates(circ)

    # Optimize with FullPeepholeOptimise
    circ_opt = circ.copy()
    FullPeepholeOptimise().apply(circ_opt)

    after = count_gates(circ_opt)

    print("Gate counts BEFORE optimization:")
    for g, c in sorted(before.items(), key=lambda x: str(x[0])):
        print(f"  {g}: {c}")
    print("Total gates before:", sum(before.values()))

    print("\nGate counts AFTER FullPeepholeOptimise:")
    for g, c in sorted(after.items(), key=lambda x: str(x[0])):
        print(f"  {g}: {c}")
    print("Total gates after:", sum(after.values()))

