import numpy as np
from math import gcd, ceil, log2
from fractions import Fraction
from qiskit import QuantumCircuit, transpile
from qiskit.circuit.library import UnitaryGate
from qiskit_aer import AerSimulator


def c_amod15(a, power, N=15):
    """Controlled multiplication by a^power mod N=15, hard-coded for the 4 work qubits."""
    if a not in [2, 4, 7, 8, 11, 13, 14]:
        raise ValueError(f"a={a} not in the hardcoded set for N=15")
    U = QuantumCircuit(4, name=f"a^{power} mod {N}")
    for _ in range(power):
        if a in [2, 13]:
            U.swap(2, 3); U.swap(1, 2); U.swap(0, 1)
        if a in [7, 8]:
            U.swap(0, 1); U.swap(1, 2); U.swap(2, 3)
        if a in [4, 11]:
            U.swap(1, 3); U.swap(0, 2)
        if a in [7, 11, 13]:
            for q in range(4):
                U.x(q)
    return U.to_gate().control(1)


def qft_dagger(qc, n):
    for qubit in range(n // 2):
        qc.swap(qubit, n - 1 - qubit)
    for j in range(n):
        for m in range(j):
            qc.cp(-np.pi / float(2 ** (j - m)), m, j)
        qc.h(j)


def qpe_order_finding(a, N, n_count=8):
    """Run QPE and return a list of candidate periods from the top measurements."""
    n_work = max(1, int(ceil(log2(N))))
    qc = QuantumCircuit(n_count + n_work, n_count)
    counting = list(range(n_count))
    work = list(range(n_count, n_count + n_work))

    for q in counting:
        qc.h(q)
    qc.x(work[0])

    for k in range(n_count):
        a_pow = pow(a, 2 ** k, N)
        if a_pow == 1:
            continue
        if N == 15 and a in [2, 4, 7, 8, 11, 13, 14]:
            U = c_amod15(a, 2 ** k, N)
            qc.append(U, [counting[k]] + work)
        else:
            size = 2 ** n_work
            mat = np.zeros((size, size), dtype=complex)
            for x in range(size):
                if gcd(x, N) == 1:
                    mat[(a_pow * x) % N, x] = 1
                else:
                    mat[x, x] = 1
            Ugate = UnitaryGate(mat, label=f"U{a_pow}").control(1)
            qc.append(Ugate, [counting[k]] + work)

    qft_dagger(qc, n_count)
    qc.measure(counting, list(range(n_count)))

    sim = AerSimulator()
    tqc = transpile(qc, sim)
    counts = sim.run(tqc, shots=4096).result().get_counts()
    print(f"Measurement counts: {counts}")

    # Collect candidate periods from all measured outcomes
    candidates = []
    for measured, c in sorted(counts.items(), key=lambda kv: -kv[1]):
        phase = int(measured, 2) / 2 ** n_count
        if phase == 0:
            continue
        frac = Fraction(phase).limit_denominator(N)
        if frac.denominator > 1:
            candidates.append(frac.denominator)
    return candidates


def shors_algorithm(N, a):
    if gcd(a, N) != 1:
        return gcd(a, N), N // gcd(a, N)

    n_count = 8
    candidates = qpe_order_finding(a, N, n_count)

    # Try each candidate period; the true period r must be even and satisfy
    # a^r = 1 (mod N). Multiples of the true period also appear, so we also
    # try dividing by small factors.
    seen = set()
    for r in candidates:
        for cand_r in [r, r // 2, r // 3, r // 4, 2 * r, 3 * r, 4 * r]:
            if cand_r < 2 or cand_r in seen:
                continue
            seen.add(cand_r)
            if pow(a, cand_r, N) != 1:
                continue
            if cand_r % 2 != 0:
                continue
            if pow(a, cand_r // 2, N) == N - 1:
                continue
            p = gcd(a ** (cand_r // 2) - 1, N)
            q = gcd(a ** (cand_r // 2) + 1, N)
            if p not in [1, N] and q not in [1, N] and p * q == N:
                return p, q
    return None, None


if __name__ == "__main__":
    N = 15
    a = 7

    print(f"Factoring N = {N} with base a = {a}")
    p, q = shors_algorithm(N, a)

    if p is not None and q is not None:
        print(f"Recovered factors: {p} and {q}")
        print(f"Verification: {p} * {q} = {p * q}")
    else:
        print("Failed to find non-trivial factors.")

