import pennylane as qml
from pennylane import numpy as np

edges = [(0, 1), (0, 3), (0, 4), (1, 2), (2, 4)]
n_qubits = 5

def cost_layer(gamma):
    for (u, v) in edges:
        qml.CNOT(wires=[u, v])
        qml.RZ(2 * gamma, wires=v)
        qml.CNOT(wires=[u, v])

def mixer_layer(alpha):
    for w in range(n_qubits):
        qml.RX(2 * alpha, wires=w)

dev = qml.device("default.qubit", wires=n_qubits, shots=10000)

@qml.qnode(dev)
def circuit(params):
    gammas, alphas = params
    for w in range(n_qubits):
        qml.Hadamard(wires=w)
    for layer in range(2):
        cost_layer(gammas[layer])
        mixer_layer(alphas[layer])
    return qml.probs(wires=range(n_qubits))

def cost(params):
    probs = circuit(params)
    exp = 0.0
    for state in range(2 ** n_qubits):
        bitstring = format(state, f"0{n_qubits}b")
        cut = 0
        for (u, v) in edges:
            if bitstring[u] != bitstring[v]:
                cut += 1
        exp += probs[state] * cut
    return -exp

np.random.seed(42)
params = np.random.uniform(0, np.pi, (2, 2), requires_grad=True)

opt = qml.AdamOptimizer(stepsize=0.1)
for i in range(300):
    params = opt.step(cost, params)

probs = circuit(params)
best_state = int(np.argmax(probs))
best_bitstring = format(best_state, f"0{n_qubits}b")
best_cut = 0
for (u, v) in edges:
    if best_bitstring[u] != best_bitstring[v]:
        best_cut += 1

print(f"Most probable bitstring: {best_bitstring}")
print(f"Cut value: {best_cut}")

