import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.qasm3 import loads
from qiskit_aer import AerSimulator

# OpenQASM 3 with mid-circuit measurement and active reset.
# Note: in OpenQASM 3, comparing a single bit to an integer literal must use
# `bit == const bool` (i.e., `== true` / `== false`), not `== 1`.
qasm_code = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[1] q;
bit[1] c;

// Prepare a quantum coin flip: put qubit in superposition
h q[0];

// Mid-circuit measurement
c[0] = measure q[0];

// Active qubit reset: if the outcome is |1>, reset the qubit to |0>
if (c[0] == true) {
    reset q[0];
}

// Apply X gate conditioned on the outcome (quantum coin flip + correction)
// If the original measurement was |1>, we flip the reset |0> to |1>
// If the original measurement was |0>, we flip |0> to |1>
// This effectively transfers the classical coin flip back to the quantum state
if (c[0] == true) {
    x q[0];
}
"""

def _collect_ops(qc):
    """Recursively collect operation names, descending into control-flow blocks."""
    names = set()
    for instruction in qc.data:
        op = instruction.operation
        names.add(op.name)
        # Descend into control-flow operation blocks (if_else, while_loop, etc.)
        for attr in ("op_blocks", "blocks", "params"):
            blocks = getattr(op, attr, None)
            if blocks is None:
                continue
            if isinstance(blocks, (list, tuple)):
                for block in blocks:
                    if isinstance(block, QuantumCircuit):
                        names |= _collect_ops(block)
            elif isinstance(blocks, QuantumCircuit):
                names |= _collect_ops(blocks)
    return names

def main():
    print("=== OpenQASM 3 Program ===")
    print(qasm_code)

    # Load the QASM 3 program into a Qiskit QuantumCircuit
    try:
        qc = loads(qasm_code)
        print("QASM 3 program successfully loaded into Qiskit QuantumCircuit.")
        print(f"Loaded circuit: {qc.num_qubits} qubit(s), {qc.num_clbits} classical bit(s), depth {qc.depth()}.")
    except Exception as e:
        print(f"Failed to load QASM 3 program: {e}")
        return

    # Run the circuit on AerSimulator to verify execution
    sim = AerSimulator()
    tqc = transpile(qc, sim)
    job = sim.run(tqc, shots=1024)
    result = job.result()
    counts = result.get_counts()
    print("\nExecution results (1024 shots):")
    for outcome, count in sorted(counts.items()):
        print(f"  {outcome}: {count}")

    # Verify the circuit contains all required constructs (including inside if-blocks)
    circuit_ops = _collect_ops(qc)
    has_h = 'h' in circuit_ops
    has_measure = 'measure' in circuit_ops
    has_reset = 'reset' in circuit_ops
    has_x = 'x' in circuit_ops
    has_if = 'if_else' in circuit_ops

    print(f"Contains H gate: {has_h}")
    print(f"Contains mid-circuit measurement: {has_measure}")
    print(f"Contains reset (active qubit reset): {has_reset}")
    print(f"Contains X gate (conditioned correction): {has_x}")
    print(f"Contains if-else control flow: {has_if}")

    if has_measure and has_reset and has_x and has_h and has_if:
        print("All required operations are present in the circuit.")
    else:
        print("WARNING: Some required operations are missing.")

if __name__ == "__main__":
    main()

from pytket import Circuit
from pytket.transform import Transform
from pytket.passes import FullPeepholeOptimise, RebaseTket


def build_circuit() -> Circuit:
    c = Circuit(6)
    for layer in range(5):
        for q in range(6):
            c.H(q)
        for q in range(5):
            c.CX(q, q + 1)
        for q in range(6):
            c.Rz(0.1 * (layer + 1) + 0.01 * q, q)
    return c


def gate_counts(c: Circuit) -> dict:
    counts: dict = {}
    for op in c:
        name = op.op.get_name()
        counts[name] = counts.get(name, 0) + 1
    return counts


def main():
    c = build_circuit()
    before = gate_counts(c)

    FullPeepholeOptimise().apply(c)
    RebaseTket().apply(c)
    after = gate_counts(c)

    print("RESULT")
    print("Before:", before)
    print("After:", after)


if __name__ == "__main__":
    main()

