import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator


def simons_oracle(circuit, s):
    """Simon's oracle for hidden string s (2-to-1 with period s).

    f(x) = x XOR (x_k * s) where k is the index of the first '1' in s.
    This guarantees f(x) = f(x XOR s) for all x.
    """
    n = len(s)
    k = s.index("1")
    for i in range(n):
        circuit.cx(i, n + i)
    for j in range(n):
        if s[j] == "1":
            circuit.cx(k, n + j)


def gaussian_elimination_gf2(equations, n):
    """Find a non-zero s with y.s = 0 (mod 2) for all measured y."""
    if not equations:
        return None
    M = np.array([[int(b) for b in eq] for eq in equations], dtype=np.uint8)
    rows, cols = M.shape
    pivot_row = 0
    pivot_cols = []
    for col in range(cols):
        found = -1
        for r in range(pivot_row, rows):
            if M[r, col] == 1:
                found = r
                break
        if found == -1:
            continue
        if found != pivot_row:
            M[[pivot_row, found]] = M[[found, pivot_row]]
        for r in range(rows):
            if r != pivot_row and M[r, col] == 1:
                M[r] = M[r] ^ M[pivot_row]
        pivot_cols.append(col)
        pivot_row += 1
        if pivot_row == rows:
            break
    rank = len(pivot_cols)
    if rank == n:
        return np.zeros(n, dtype=int)
    free_cols = [c for c in range(n) if c not in pivot_cols]
    if not free_cols:
        return np.zeros(n, dtype=int)
    s = np.zeros(n, dtype=int)
    s[free_cols[0]] = 1
    for idx, col in enumerate(pivot_cols):
        s[col] = int(M[idx, free_cols[0]])
    return s


def main():
    s_hidden = "0001"
    n = len(s_hidden)
    circuit = QuantumCircuit(2 * n, n)
    for i in range(n):
        circuit.h(i)
    simons_oracle(circuit, s_hidden)
    for i in range(n):
        circuit.h(i)
    for i in range(n):
        circuit.measure(i, i)

    simulator = AerSimulator()
    transpiled = transpile(circuit, simulator)
    shots = 8192
    result = simulator.run(transpiled, shots=shots).result()
    counts = result.get_counts()
    print("Measurement outcomes:", counts)

    # Qiskit reports bitstrings with qubit 0 as the rightmost bit.
    # Reverse each outcome so that the string index matches the qubit index.
    equations = [outcome[::-1] for outcome in counts.keys() if outcome != "0" * n]
    if not equations:
        equations = [outcome[::-1] for outcome in counts.keys()]
    print("Linear equations (y values):", equations)

    s_recovered = gaussian_elimination_gf2(equations, n)
    s_recovered_str = "".join(map(str, s_recovered))
    print("Hidden period s:", s_hidden)
    print("Recovered period s:", s_recovered_str)
    if s_recovered_str == s_hidden:
        print("SUCCESS: Recovered period matches hidden period.")
    else:
        print("FAILURE: Recovered period does not match.")


if __name__ == "__main__":
    main()

