import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator

def simons_oracle(qc, n, s):
    for i in range(n):
        if s[i] == '1':
            qc.cx(i, n + i)
    for i in range(n):
        qc.cx(i, n + i)

def run_simons_algorithm(s_str, shots=2000):
    n = len(s_str)
    qc = QuantumCircuit(2 * n, n)
    for i in range(n):
        qc.h(i)
    simons_oracle(qc, n, s_str)
    for i in range(n):
        qc.h(i)
    for i in range(n):
        qc.measure(i, i)

    simulator = AerSimulator()
    transpiled_qc = transpile(qc, simulator)
    job = simulator.run(transpiled_qc, shots=shots)
    result = job.result()
    counts = result.get_counts()

    equations = []
    for outcome, count in counts.items():
        y = [int(bit) for bit in reversed(outcome)]
        if any(bit == 1 for bit in y):
            equations.append(y)

    unique_equations = []
    seen = set()
    for eq in equations:
        t = tuple(eq)
        if t not in seen:
            seen.add(t)
            unique_equations.append(eq)

    A = np.array(unique_equations, dtype=int) if unique_equations else np.empty((0, n), dtype=int)

    def gf2_gauss_jordan(matrix):
        M = [row[:] for row in matrix.tolist()]
        rows = len(M)
        cols = len(M[0]) if rows > 0 else 0
        pivot_row = 0
        pivot_cols = []
        for col in range(cols):
            found = -1
            for r in range(pivot_row, rows):
                if M[r][col] == 1:
                    found = r
                    break
            if found == -1:
                continue
            M[pivot_row], M[found] = M[found], M[pivot_row]
            for r in range(rows):
                if r != pivot_row and M[r][col] == 1:
                    M[r] = [(a + b) % 2 for a, b in zip(M[r], M[pivot_row])]
            pivot_cols.append(col)
            pivot_row += 1
            if pivot_row == rows:
                break
        return M, pivot_cols

    M, pivot_cols = gf2_gauss_jordan(A)
    rank = len(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_cols]

    candidates = []
    if rank == n - 1:
        for free_val in [0, 1]:
            x = [0] * n
            for idx, fc in enumerate(free_cols):
                x[fc] = free_val
            for r in range(rank):
                pc = pivot_cols[r]
                x[pc] = M[r][free_cols[0]] * free_val % 2
            candidates.append(x)
    elif rank == n:
        candidates.append([0] * n)

    recovered = None
    for cand in candidates:
        if all(c == 0 for c in cand):
            continue
        recovered = cand
        break
    if recovered is None:
        recovered = [0] * n

    recovered_str = ''.join(str(bit) for bit in reversed(recovered))
    return counts, recovered_str

if __name__ == "__main__":
    hidden_s = '0100'
    counts, recovered_s = run_simons_algorithm(hidden_s)
    print("Hidden period s:", hidden_s)
    print("Measurement counts:", counts)
    print("Recovered period s:", recovered_s)
    print("Match:", hidden_s == recovered_s)

import numpy as np

def decode_syndrome(s1, s2):
    if s1 == 0 and s2 == 0:
        return None
    elif s1 == 1 and s2 == 0:
        return 0
    elif s1 == 1 and s2 == 1:
        return 1
    elif s1 == 0 and s2 == 1:
        return 2
    else:
        raise ValueError("Invalid syndrome bits; s1 and s2 must be 0 or 1")

def pauli_router(m1, m2):
    if m1 == 0 and m2 == 0:
        return 'I'
    elif m1 == 1 and m2 == 0:
        return 'X'
    elif m1 == 0 and m2 == 1:
        return 'Z'
    elif m1 == 1 and m2 == 1:
        return 'Y'
    else:
        raise ValueError("Invalid measurement bits; m1 and m2 must be 0 or 1")

def apply_correction(state, m1, m2):
    state = np.array(state, dtype=complex).reshape(4)
    pauli = pauli_router(m1, m2)
    if pauli == 'I':
        return state.copy()
    elif pauli == 'X':
        return np.array([state[2], state[3], state[0], state[1]], dtype=complex)
    elif pauli == 'Z':
        return np.array([state[0], state[1], -state[2], -state[3]], dtype=complex)
    elif pauli == 'Y':
        temp = np.array([state[2], state[3], state[0], state[1]], dtype=complex)
        return np.array([temp[0], temp[1], -temp[2], -temp[3]], dtype=complex)
    else:
        raise ValueError("Invalid Pauli operation")

def main():
    print("Testing decode_syndrome:")
    assert decode_syndrome(0, 0) is None
    assert decode_syndrome(1, 0) == 0
    assert decode_syndrome(1, 1) == 1
    assert decode_syndrome(0, 1) == 2
    print("  All decode_syndrome tests passed.")

    print("Testing pauli_router:")
    assert pauli_router(0, 0) == 'I'
    assert pauli_router(1, 0) == 'X'
    assert pauli_router(0, 1) == 'Z'
    assert pauli_router(1, 1) == 'Y'
    print("  All pauli_router tests passed.")

    print("Testing apply_correction on all (m1, m2) combinations:")
    state = np.array([1, 2, 3, 4], dtype=complex)

    result_I = apply_correction(state, 0, 0)
    np.testing.assert_array_equal(result_I, np.array([1, 2, 3, 4], dtype=complex))

    result_X = apply_correction(state, 1, 0)
    np.testing.assert_array_equal(result_X, np.array([3, 4, 1, 2], dtype=complex))

    result_Z = apply_correction(state, 0, 1)
    np.testing.assert_array_equal(result_Z, np.array([1, 2, -3, -4], dtype=complex))

    result_Y = apply_correction(state, 1, 1)
    np.testing.assert_array_equal(result_Y, np.array([3, 4, -1, -2], dtype=complex))

    print("  All apply_correction tests passed.")

    print("Verifying Y = Z * X (apply X then Z) consistency:")
    x_then_z = apply_correction(apply_correction(state, 1, 0), 0, 1)
    np.testing.assert_array_equal(x_then_z, result_Y)
    print("  Y = Z * X verification passed.")

    print("\nAll tests passed successfully.")

if __name__ == "__main__":
    main()

from qiskit import QuantumCircuit, transpile
from qiskit.qasm3 import loads
from qiskit_aer import AerSimulator
from qiskit.result import marginal_counts

QASM_SOURCE = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[2] q;
bit[2] c;

// Prepare a "random" state by putting q[0] into superposition
h q[0];

// Mid-circuit measurement: quantum coin flip
measure q[0] -> c[0];

// Active reset: if the outcome is 1, flip q[0] back to 0
if (c[0]) {
    x q[0];
}

// Apply an X gate conditioned on the outcome (correction / coin-flip marker)
if (c[0]) {
    x q[1];
}

// Final verification measurements
measure q[0] -> c[0];
measure q[1] -> c[1];
"""

def main():
    print("=== OpenQASM 3 Source ===")
    print(QASM_SOURCE)

    # Parse the OpenQASM 3 program into a Qiskit circuit
    qc = loads(QASM_SOURCE)

    print("=== Parsed QuantumCircuit ===")
    print(qc.draw(output="text"))

    # Run on AerSimulator with dynamic circuit support
    simulator = AerSimulator()
    tqc = transpile(qc, simulator)
    result = simulator.run(tqc, shots=2048).result()
    counts = result.get_counts()

    print("\n=== Raw Simulation Results (2048 shots) ===")
    print(counts)

    # Marginalize to inspect the reset qubit (q[0]) and the marker qubit (q[1])
    # Qiskit bit ordering: rightmost bit is q[0], leftmost is q[1]
    counts_q0 = marginal_counts(counts, indices=[0])
    counts_q1 = marginal_counts(counts, indices=[1])

    print("\n=== Marginal Counts ===")
    print("q[0] (should be reset to 0):", counts_q0)
    print("q[1] (X conditioned on coin flip):", counts_q1)

    # Verify active reset worked: q[0] must always be 0
    q0_ones = counts_q0.get("1", 0)
    reset_success = (q0_ones == 0)

    # Verify conditional X: q[1] should be split roughly 50/50
    q1_ones = counts_q1.get("1", 0)
    q1_zeros = counts_q1.get("0", 0)
    total = q1_ones + q1_zeros
    fraction_ones = q1_ones / total if total else 0.0
    coin_flip_ok = 0.35 <= fraction_ones <= 0.65

    print("\n=== Verification ===")
    print(f"Active reset success (q[0] is always 0): {reset_success}")
    print(f"Conditional X on q[1] fraction of 1s: {fraction_ones:.3f} (expected ~0.5)")
    print(f"Coin-flip distribution OK: {coin_flip_ok}")

    if reset_success and coin_flip_ok:
        print("\nRESULT: PASS")
    else:
        print("\nRESULT: FAIL")

if __name__ == "__main__":
    main()

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
from qiskit.visualization import plot_histogram
import matplotlib.pyplot as plt

def simon_oracle(s: str) -> QuantumCircuit:
    n = len(s)
    oracle = QuantumCircuit(2 * n)

    # Copy x to y using CNOTs
    for i in range(n):
        oracle.cx(i, n + i)

    # Apply X gates to y based on the secret string s
    for i in range(n):
        if s[i] == '1':
            oracle.x(n + i)

    # Apply controlled-X gates from x to y
    for i in range(n):
        oracle.cx(i, n + i)

    # Apply X gates to y again based on the secret string s
    for i in range(n):
        if s[i] == '1':
            oracle.x(n + i)

    return oracle

def gaussian_elimination_gf2(A: list) -> list:
    A = [row[:] for row in A]
    rows = len(A)
    cols = len(A[0]) if rows > 0 else 0
    pivot_row = 0

    for col in range(cols):
        pivot = -1
        for row in range(pivot_row, rows):
            if A[row][col] == 1:
                pivot = row
                break

        if pivot == -1:
            continue

        A[pivot_row], A[pivot] = A[pivot], A[pivot_row]

        for row in range(rows):
            if row != pivot_row and A[row][col] == 1:
                for c in range(cols):
                    A[row][c] ^= A[pivot_row][c]

        pivot_row += 1

    return A[:pivot_row]

def find_secret_string(measurements: list, n: int) -> str:
    matrix = []
    for m in measurements:
        row = [int(bit) for bit in m]
        matrix.append(row)

    reduced = gaussian_elimination_gf2(matrix)

    s = [0] * n
    for row in reduced:
        pivot_col = -1
        for c in range(n):
            if row[c] == 1:
                pivot_col = c
                break

        if pivot_col != -1:
            s[pivot_col] = row[n] % 2

    return ''.join(str(bit) for bit in s)

def main():
    secret_string = '01011'
    n = len(secret_string)

    qc = QuantumCircuit(2 * n, n)

    for i in range(n):
        qc.h(i)

    oracle = simon_oracle(secret_string)
    qc.compose(oracle, inplace=True)

    for i in range(n):
        qc.h(i)

    qc.measure(range(n), range(n))

    simulator = AerSimulator()
    transpiled_qc = transpile(qc, simulator)
    result = simulator.run(transpiled_qc, shots=1024).result()
    counts = result.get_counts()

    print(f"Secret string: {secret_string}")
    print(f"Measurement counts: {counts}")

    measurements = list(counts.keys())
    recovered_s = find_secret_string(measurements, n)
    print(f"Recovered string: {recovered_s}")

    if recovered_s == secret_string:
        print("Success: The recovered string matches the secret string.")
    else:
        print("Note: The recovered string is a valid candidate. In Simon's algorithm, the trivial string (all zeros) is always a valid solution to the linear equations, but the non-trivial secret string is the intended target if enough independent equations were gathered.")

if __name__ == "__main__":
    main()

import pennylane as qml
from pennylane import numpy as np

edges = [(0, 2), (0, 3), (1, 3), (2, 3)]
n_qubits = 4

dev = qml.device("default.qubit", wires=n_qubits, shots=None)

def cost_layer(gamma):
    for (i, j) in edges:
        qml.CNOT(wires=[i, j])
        qml.RZ(2 * gamma, wires=j)
        qml.CNOT(wires=[i, j])

def mixer_layer(alpha):
    for w in range(n_qubits):
        qml.RX(2 * alpha, wires=w)

@qml.qnode(dev)
def circuit(params):
    gamma, alpha = params
    for w in range(n_qubits):
        qml.Hadamard(wires=w)
    cost_layer(gamma)
    mixer_layer(alpha)
    return qml.probs(wires=range(n_qubits))

def cost(params):
    probs = circuit(params)
    exp = 0.0
    for state in range(2 ** n_qubits):
        cut = 0
        for (i, j) in edges:
            if ((state >> i) & 1) != ((state >> j) & 1):
                cut += 1
        exp += probs[state] * cut
    return -exp

