import pennylane as qml
from pennylane import numpy as np

np.random.seed(42)

num_qubits = 1
dev = qml.device("default.qubit", wires=num_qubits)

def layer(weights):
    qml.Rot(weights[0], weights[1], weights[2], wires=0)

@qml.qnode(dev)
def circuit(weights, x):
    qml.RX(x, wires=0)
    for w in weights:
        layer(w)
    return qml.expval(qml.PauliZ(0))

def variational_classifier(weights, x):
    return circuit(weights, x)

def square_loss(labels, predictions):
    loss = 0
    for l, p in zip(labels, predictions):
        loss = loss + (l - p) ** 2
    return loss / len(labels)

def accuracy(labels, predictions):
    acc = 0
    for l, p in zip(labels, predictions):
        if np.abs(l - p) < 1e-5:
            acc = acc + 1
    return acc / len(labels)

X = np.linspace(-np.pi, np.pi, 30, requires_grad=False)
Y = np.sign(np.sin(1 * X))
Y = np.where(Y == 0, 1, Y)

num_layers = 3
weights = 0.01 * np.random.randn(num_layers, 3, requires_grad=True)
opt = qml.GradientDescentOptimizer(stepsize=0.1)
batch_size = 10

for it in range(100):
    batch_index = np.random.randint(0, len(X), batch_size)
    X_batch = X[batch_index]
    Y_batch = Y[batch_index]

    def cost(w):
        preds = [variational_classifier(w, x) for x in X_batch]
        return square_loss(Y_batch, preds)

    weights = opt.step(cost, weights)

    if it % 10 == 0:
        preds = [variational_classifier(weights, x) for x in X]
        pred_labels = [1 if p >= 0 else -1 for p in preds]
        acc = accuracy(Y, pred_labels)
        loss = square_loss(Y, preds)
        print(f"Iter: {it:3d} | Loss: {loss:.4f} | Accuracy: {acc:.4f}")

preds = [variational_classifier(weights, x) for x in X]
pred_labels = [1 if p >= 0 else -1 for p in preds]
final_acc = accuracy(Y, pred_labels)
print(f"Final training accuracy: {final_acc:.4f}")

