include "stdgates.inc";

qubit[1] q;
bit[1] c;

// Prepare a superposition (quantum coin flip)
h q[0];

// Mid-circuit measurement
c[0] = measure q[0];

// Active qubit reset: if the qubit is |1>, reset it to |0>
if (c[0]) {
    x q[0];
}

// Apply an X gate conditioned on the outcome (correction / flip)
if (c[0]) {
    x q[0];
}

// Final measurement to verify the state
bit[1] d;
d[0] = measure q[0];
"""

def main():
    # Load the OpenQASM 3 program into a Qiskit circuit
    qc = loads(qasm_program)

    # Use AerSimulator for simulation (supports mid-circuit measurement and dynamic circuits)
    simulator = AerSimulator()

    # Transpile for the simulator backend
    tqc = transpile(qc, simulator)

    # Run the circuit with many shots to verify behavior
    shots = 4096
    result = simulator.run(tqc, shots=shots).result()
    counts = result.get_counts()

    print("OpenQASM 3 Program:")
    print(qasm_program)
    print("Transpiled Circuit:")
    print(tqc)
    print(f"Measurement counts ({shots} shots):", counts)

    # Verification: The final measurement 'd' should always be '0'
    # because the active reset brings the qubit back to |0> after the first measurement,
    # and the conditional X gate flips it to |1> only if c[0]==1, but since the qubit
    # was reset to |0>, the second X (conditioned on the same c[0]) flips it to |1>...
    # Actually, let's trace through:
    #   If c[0]=0: q is |0>, no reset, no X -> final d=0
    #   If c[0]=1: q is |1>, reset to |0>, then X -> |1> -> final d=1
    # So d should match c. Let's verify the distribution is roughly 50/50.
    if "1" in counts and "0" in counts:
        ratio = counts["0"] / shots
        print(f"Fraction of '0' outcomes: {ratio:.3f} (expected ~0.5)")
    elif "0" in counts:
        print("All outcomes are '0'")
    elif "1" in counts:
        print("All outcomes are '1'")

    # Also print the QASM exported by Qiskit to confirm round-trip
    print("\nQiskit-exported QASM3:")
    print(dumps(qc))

if __name__ == "__main__":
