    shots = 8192
    result = simulator.run(transpiled, shots=shots).result()
    counts = result.get_counts()
    print("Measurement outcomes:", counts)

    # Qiskit reports bitstrings with qubit 0 as the rightmost bit.
    # Reverse each outcome so that the string index matches the qubit index.
    equations = [outcome[::-1] for outcome in counts.keys() if outcome != "0" * n]
    if not equations:
        equations = [outcome[::-1] for outcome in counts.keys()]
    print("Linear equations (y values):", equations)

    s_recovered = gaussian_elimination_gf2(equations, n)
    s_recovered_str = "".join(map(str, s_recovered))
    print("Hidden period s:", s_hidden)
    print("Recovered period s:", s_recovered_str)
    if s_recovered_str == s_hidden:
        print("SUCCESS: Recovered period matches hidden period.")
    else:
        print("FAILURE: Recovered period does not match.")


if __name__ == "__main__":
    main()

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
from qiskit.quantum_info import Statevector

def simons_oracle(qc, n, s):
    s_int = int(s, 2)
    for i in range(n):
        qc.cx(i, n + i)
    if s_int != 0:
        for i in range(n):
            if (s_int >> i) & 1:
                qc.cx(i, n + i)

def solve_linear_system_gf2(equations, n):
    if not equations:
        return None
    A = np.array(equations, dtype=int)
    rows = A.shape[0]
    pivot_row = 0
    pivot_cols = []
    for col in range(n):
        found = -1
        for r in range(pivot_row, rows):
            if A[r, col] == 1:
                found = r
                break
        if found == -1:
            continue
        if found != pivot_row:
            A[[found, pivot_row]] = A[[pivot_row, found]]
        for r in range(rows):
            if r != pivot_row and A[r, col] == 1:
                A[r] = (A[r] + A[pivot_row]) % 2
        pivot_cols.append(col)
        pivot_row += 1
        if pivot_row == rows:
            break
    rank = len(pivot_cols)
    if rank == n:
        return np.zeros(n, dtype=int)
    free_cols = [c for c in range(n) if c not in pivot_cols]
    if not free_cols:
        return None
    solution = np.zeros(n, dtype=int)
    solution[free_cols[0]] = 1
    for i, pc in enumerate(pivot_cols):
        if A[i, free_cols[0]] == 1:
            solution[pc] = 1
    return solution

def run_simons_algorithm(s, shots=200):
    n = len(s)
    qc = QuantumCircuit(2 * n, n)
    for i in range(n):
        qc.h(i)
    simons_oracle(qc, n, s)
    for i in range(n):
        qc.h(i)
    for i in range(n):
        qc.measure(i, i)
    simulator = AerSimulator()
    tqc = transpile(qc, simulator)
    result = simulator.run(tqc, shots=shots).result()
    counts = result.get_counts()
    equations = []
    for outcome in counts.keys():
        y = [int(b) for b in reversed(outcome)]
        if any(v == 1 for v in y):
            equations.append(y)
    solution = solve_linear_system_gf2(equations, n)
    if solution is None:
        return None, counts
    recovered = ''.join(str(int(b)) for b in reversed(solution))
    return recovered, counts

if __name__ == "__main__":
    s = '011'
    recovered, counts = run_simons_algorithm(s)
    print(f"Hidden period s: {s}")
    print(f"Measurement outcomes: {counts}")
    print(f"Recovered period: {recovered}")
    print(f"Match: {recovered == s}")

import tempfile
import os
from qiskit import qasm3, transpile
from qiskit.providers.basic_provider import BasicProvider

qasm_code = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[3] q;
bit[3] c;

h q[0];
cx q[0], q[1];
cx q[1], q[2];

c[0] = measure q[0];
c[1] = measure q[1];
c[2] = measure q[2];
"""

with tempfile.NamedTemporaryFile(mode='w', suffix='.qasm', delete=False) as f:
    f.write(qasm_code)
    qasm_path = f.name

try:
    circuit = qasm3.load(qasm_path)
    backend = BasicProvider().get_backend("basic_simulator")
    transpiled = transpile(circuit, backend)
    result = backend.run(transpiled, shots=2000).result()
    counts = result.get_counts()
    print("GHZ state measurement counts (2000 shots):")
    print(counts)
finally:
    os.remove(qasm_path)
